from lib import *
S = SS('j264')
steps = [
    step("没有任何配置时(JDK 21):System.getLogger(\"demo.app\") 的实现类是 sun.util.logging.internal.LoggingProviderImpl$JULWrapper(包装 java.util.logging)。TRACE 与 DEBUG 的消息没有输出,INFO 输出为 “INFO: 消息 level=INFO”,WARNING 输出 WARNING,ERROR 输出的级别名是 SEVERE;isLoggable 是 TRACE=false、DEBUG=false、INFO=true、WARNING=true、ERROR=true、ALL=false、OFF=true。默认格式带时间、调用类与方法(Main main)。", t=tl(S(1)), done=lidx(S(1), 'INFO: 消息 level=INFO', 'WARNING: 消息'), mark=lidx(S(1), 'SEVERE: 消息 level=ERROR', 'isLoggable:TRACE=false'), kv=KV([['默认可见', 'INFO、WARNING、ERROR(输出为 SEVERE)'], ['默认不可见', 'TRACE、DEBUG'], ['后端', 'java.util.logging(JULWrapper)']], ['后端'])),
    step("通过 java.util.logging 的配置文件把 demo.app 的级别设为 ALL、ConsoleHandler 也设为 ALL(-Djava.util.logging.config.file=logging.properties)之后,五个级别都输出:TRACE 对应 [FINER]、DEBUG 对应 [FINE]、INFO、WARNING、ERROR 对应 [SEVERE];isLoggable(TRACE) 与 isLoggable(DEBUG) 变成 true。System.Logger 本身没有配置方法,级别由后端决定。", t=tl(S(2)), done=lidx(S(2), '[FINER]', '[FINE]'), mark=lidx(S(2), '[SEVERE]', 'isLoggable:TRACE=true'), kv=KV([['TRACE → FINER', '[FINER] 输出'], ['DEBUG → FINE', '[FINE] 输出'], ['ERROR → SEVERE', '[SEVERE] 输出']], ['TRACE → FINER'])),
    step("惰性消息:DEBUG 被禁用时,1000 次 log(level, Supplier) 之后 Supplier 被执行了 0 次;而 log(level, expensive()) 里 expensive() 在调用 log 之前就执行了,1000 次;INFO 启用时 Supplier 被执行 1000 次(并输出 1000 条)。想让昂贵的消息在禁用时不计算,必须传 Supplier 或用 isLoggable 守卫。", t=tl(S(3)), done=lidx(S(3), 'DEBUG 被禁用:1000 次 log(level, Supplier)'), mark=lidx(S(3), 'expensive():被执行了 1000 次', 'INFO 启用'), b=bars([['Supplier(DEBUG 禁用)', 0, '0 次'], ['直接调用 expensive()', 1000, '1000 次'], ['INFO 启用的 Supplier', 1000, '1000 次']], 1000, done=[0, 1, 2]), kv=KV([['log(level, Supplier)', '禁用时 0 次求值'], ['log(level, expensive())', '禁用时仍然求值 1000 次']], ['log(level, expensive())'])),
    step("消息格式:占位符是 java.text.MessageFormat 的 {0},不是 %s。log(INFO, \"带占位符 {0} 和 {1}\", \"A\", 42) 输出 “带占位符 A 和 42”;“用 %s 和 %d 占位” 原样输出,没有替换;两个连续的单引号 ''单引号'' 输出成 '单引号';{0,number,#.##} 把 3.14159 格式化成 3.14;带异常的重载输出堆栈;没有参数时 “{0}” 原样保留;null 消息输出 null。写日志时把 %s 用法带进来会得到未替换的文本。", t=tl(S(4)), done=lidx(S(4), '带占位符 A 和 42', '用 %s 和 %d 占位'), mark=lidx(S(4), '引号', '3.14 与', '带异常', '没有参数但含', 'p1 的参数是数组'), kv=KV([['{0} / {1}', '被 MessageFormat 替换'], ['%s / %d', '原样输出,不替换'], ['单引号', '要写成 \'\' 才输出一个 \'']], ['%s / %d'])),
    step("被禁用的日志调用的成本(DEBUG 被禁用,5,000,000 次,第 3 轮):log(DEBUG, Supplier) 11 ms(2.1 ns/次,与空循环 11 ms 一样);log(DEBUG, \"x={0}\", i) 12 ms(2.5 ns);if (isLoggable) 15 ms(3.1 ns);log(DEBUG, \"x=\" + i) 54 ms(10.8 ns)——字符串拼接在调用 log 之前就做了。被禁用时 Supplier、参数形式与 isLoggable 的成本几乎为零,拼接是其中唯一明显更贵的写法。", t=tl(S(5)), done=lidx(S(5), 'log(DEBUG, Supplier)', '参数形式'), mark=lidx(S(5), '字符串拼接', 'isLoggable', '空循环'), b=bars([['Supplier', 11, '11 ms'], ['参数形式 {0}', 12, '12 ms'], ['isLoggable 守卫', 15, '15 ms'], ['字符串拼接', 54, '54 ms'], ['空循环', 11, '11 ms']], 54, done=[0, 1, 2, 3, 4]), kv=KV([['Supplier / 参数形式 / isLoggable', '2.1–3.1 ns/次,接近空循环'], ['字符串拼接', '10.8 ns/次']], ['字符串拼接'])),
    step("自定义 System.LoggerFinder:在 classpath 上放一个 META-INF/services/java.lang.System$LoggerFinder 指向自己的 MyFinder,所有 System.getLogger 的输出都走它——输出变成 [CUSTOM INFO] demo.app : …、[CUSTOM DEBUG]、[CUSTOM WARNING] other.name,getLoggerFinder() 返回 MyFinder。更有意思的是 JDK 自己也走这个入口:程序调用 System.exit(3)(退出码 3)时,自定义 finder 收到了 [CUSTOM DEBUG] java.lang.Runtime (模块 java.base) : Runtime.exit() called with status: 3,带异常 Throwable: Runtime.exit(3)(JDK 21 里 Runtime.exit 会通过 System.Logger 记录)。", t=tl(S(6)), done=lidx(S(6), '不带 System.exit', '[CUSTOM INFO] demo.app'), mark=lidx(S(6), '[CUSTOM WARNING] other.name', 'finder = MyFinder', '调用 System.exit(3)', 'Runtime.exit() called with status: 3'), kv=KV([['MyFinder(ServiceLoader)', '接管所有 System.getLogger'], ['System.exit(3)', 'JDK 通过 java.lang.Runtime 这个 logger 记录退出(DEBUG)']], ['System.exit(3)'])),
]
A = mkartj('j264', 264, 'Java,日志,System.Logger,java.util.logging,LoggerFinder,模块,真实验证,动画演示',
    '在 JDK 21 上实测 System.Logger:默认后端是 java.util.logging(TRACE / DEBUG 不输出,ERROR 显示为 SEVERE);Supplier 在级别禁用时不求值而 expensive() 直接调用求值 1000 次;占位符是 MessageFormat 的 {0} 而不是 %s;禁用时字符串拼接 10.8 ns 而 Supplier 约 2 ns;自定义 LoggerFinder 能收到 JDK 的 Runtime.exit 日志。',
    'System.Logger 是 JDK 自带的、与具体日志框架无关的日志门面。这篇用真实运行回答:它默认走哪里、级别怎么映射、占位符怎么写、禁用时的开销,以及怎样用 LoggerFinder 把它接到自己的后端——并看到 JDK 自己也在用它。',
    [('JULWrapper', 'JDK 21 默认的 System.Logger 实现(包装 java.util.logging;ERROR 输出为 SEVERE)'), ('0 vs 1000', '级别被禁用时 Supplier 与直接传 expensive() 的求值次数'), ('Runtime.exit() called with status: 3', '自定义 LoggerFinder 收到的 JDK 内部日志(DEBUG 级别,logger 名 java.lang.Runtime)')],
    [('默认后端', None), ('配置级别', None), ('惰性消息', None), ('占位符', None), ('禁用时的成本', None), ('自定义 LoggerFinder', None)],
    steps, [ENV_J + '。JDK 21.0.12;默认后端与 Runtime.exit 日志是 JDK 21 的行为(其它版本可能不同);成本测量是 System.nanoTime 的单次 5,000,000 次循环(第 3 轮),不是 JMH', '没有验证:模块路径下以 provides … with 声明的 LoggerFinder、SLF4J / Log4j2 / Logback 提供的 LoggerFinder 适配器、ResourceBundle 本地化消息、JDK 的其它内部 logger(java.net.http 等)的输出、多线程下的性能'], 'System.Logger')
